const parseDecimal=(value:unknown)=>{
 const raw=String(value??"").trim().replace(/\s/g,"");
 if(!raw)return 0;
 const normalized=raw.includes(",")?raw.replace(/\./g,"").replace(",","."):raw;
 const parsed=Number(normalized);
 return Number.isFinite(parsed)&&parsed>0?parsed:0;
};
const normalizeMeasure=(field:"weight"|"width"|"length"|"height",value:unknown)=>{
 let parsed=parseDecimal(value);
 // O Bling e etiquetas de fornecedores frequentemente informam peso em gramas.
 if(field==="weight"&&parsed>=100)parsed/=1000;
 // Medidas acima de 200 normalmente chegam em milímetros; o anúncio usa centímetros.
 if(field!=="weight"&&parsed>200)parsed/=10;
 return parsed?String(Math.round(parsed*100)/100):"";
};
const normalizeMeasures=(source:any)=>({
 ...source,
 weight:normalizeMeasure("weight",source.weight),
 width:normalizeMeasure("width",source.width),
 length:normalizeMeasure("length",source.length),
 height:normalizeMeasure("height",source.height)
});
