 <section className="listing-stats"><div><strong>{items.length}</strong><span>Total</span></div><div><strong>{count("preparacao")}</strong><span>Em preparação</span></div><div><strong>{count("pronto")}</strong><span>Prontos</span></div><div><strong>{count("publicado")}</strong><span>Publicados</span></div></section>
